def schedule(durations, deps, workers):
    import heapq
    from collections import deque

    if deps is None:
        deps = {}

    tasks = set(durations)

    # Validate task names appearing as keys in deps.
    for task in deps:
        if task not in tasks:
            raise ValueError("deps references unknown task")

    indeg = {}
    children = {task: [] for task in tasks}

    # Build unique dependency graph and validate dependency names.
    for task in tasks:
        raw_deps = deps.get(task, ())
        if raw_deps is None:
            raw_deps = ()

        predecessors = set(raw_deps)
        for pred in predecessors:
            if pred not in tasks:
                raise ValueError("deps references unknown dependency")
            children[pred].append(task)

        indeg[task] = len(predecessors)

    # Cycle detection via Kahn's algorithm.
    topo_indeg = dict(indeg)
    q = deque(task for task in tasks if topo_indeg[task] == 0)
    processed = 0

    while q:
        u = q.popleft()
        processed += 1
        for v in children[u]:
            topo_indeg[v] -= 1
            if topo_indeg[v] == 0:
                q.append(v)

    if processed != len(tasks):
        raise ValueError("dependencies contain a cycle")

    if not tasks:
        return (0, {})

    if workers < 1:
        raise ValueError("workers must be at least 1")

    # Ready tasks are ordered by longest duration, then smallest name.
    ready = [(-durations[task], task) for task in tasks if indeg[task] == 0]
    heapq.heapify(ready)

    finish = []          # min-heap of (finish_time, task)
    starts = {}
    running = 0
    started = 0
    now = 0
    makespan = 0
    total = len(tasks)

    while started < total:
        # Process all tasks finishing at the current time.
        while finish and finish[0][0] <= now:
            _, finished = heapq.heappop(finish)
            running -= 1

            for succ in children[finished]:
                indeg[succ] -= 1
                if indeg[succ] == 0:
                    heapq.heappush(ready, (-durations[succ], succ))

        # Start as many ready tasks as possible on idle workers.
        while ready and running < workers:
            _, task = heapq.heappop(ready)

            starts[task] = now
            running += 1
            started += 1

            done = now + durations[task]
            heapq.heappush(finish, (done, task))

            if done > makespan:
                makespan = done

        if started == total:
            break

        if not finish:
            raise ValueError("dependencies contain a cycle")

        now = finish[0][0]

    return (makespan, starts)
